%root_path = fileparts(mfilename("fullpath"));
%root_path = pwd;

% retrieve selected cuts used for further fitting
[NG_FFCutsFits,CutFitFileNG] = recover_selected_cuts('NG_FFCutsFits', ...
    'e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');

%%
fn = fieldnames(NG_FFCutsFits);
nf = 11 %[output:888861f2]
%for i = 11:numel(fn)
%selectCuts = fn{nf};
selectCuts = 'Ei400_off110NGminFFns' %[output:3b59efcf]
if ismember(selectCuts(1:3),{'msk','dat'})||...
        contains(selectCuts,'all_fit_par')
    %continue
    error('Can not fit field: %s',selectCuts);
end

fprintf('Processing cuts: %s \n', selectCuts); %[output:1fa9b020]
cuts_list = NG_FFCutsFits.(selectCuts);
if ~iscell(cuts_list)
    cuts_list = {cuts_list};
end
if contains(selectCuts,'Ei200')
    min_Ei = 30;        
    mi = maps_instrument(200,600,'S');
end
if contains(selectCuts,'Ei400')
    min_Ei = 40;            
    mi = maps_instrument(401,600,'S');
end
if contains(selectCuts,'Ei800')
    min_Ei = 70;            
    mi = maps_instrument(786,600,'S');
end
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
for j=1:numel(cuts_list) %[output:group:3ed3cc30]
    cuts_list{j} = cuts_list{j}.set_instrument(mi);
    cuts_list{j} = cuts_list{j}.set_sample(sample);
    plot(cuts_list{j}); lz 0 1; keep_figure; %[output:17d028c7]
end %[output:group:3ed3cc30]
dir_name  = "NG";

dE_step = 2; %original energy transfer step data were binned to. No point in going finer
half_dE = 5; % half width of data binning

en_mm = cuts_list{1}.data.img_range(:,4);
en_mm(1) = max(min_Ei,en_mm(1));
%en_mm(1) = 100;
%en_mm(2) = 380;
cut_en = en_mm(1)+half_dE:2*half_dE:(en_mm(2)-half_dE);

cut_dimensions = 1;
NG_FFCutsFits.(selectCuts) = cuts_list;
%%
NG_FFCutsFits = fit_multicutsFF_along_direction(... %[output:group:96e36f83] %[output:512f90cb] %[output:5cfdd3f6] %[output:9b9afdfe] %[output:9f3e0723] %[output:1b16f6b6] %[output:567f1846] %[output:5761204b] %[output:63f9f7de] %[output:05ea293a] %[output:04abf11d] %[output:02e8ff5f] %[output:45c20a08] %[output:8de8017e] %[output:7c1ca537] %[output:8f55b56a] %[output:802bcbc7] %[output:6325fbd8] %[output:7656ee01] %[output:9d257861] %[output:6de50f24] %[output:13262997] %[output:7940e136] %[output:78e12ac8] %[output:06c3032f] %[output:505db29e] %[output:07868670] %[output:8b7637fa] %[output:2dc50865] %[output:7a202e2e] %[output:3b335258] %[output:340c105f] %[output:45bd952c] %[output:6d3a350b] %[output:947c2699] %[output:3378c2de] %[output:2ed18173] %[output:0a104c19] %[output:0f39da05] %[output:6ec9f0b4] %[output:93e21ff1] %[output:371ac3d9] %[output:54fbfde4] %[output:89024e34] %[output:8d9a759d]
    NG_FFCutsFits,selectCuts,cut_dimensions,cut_en,dE_step,half_dE,true); %[output:group:96e36f83] %[output:512f90cb] %[output:5cfdd3f6] %[output:9b9afdfe] %[output:9f3e0723] %[output:1b16f6b6] %[output:567f1846] %[output:5761204b] %[output:63f9f7de] %[output:05ea293a] %[output:04abf11d] %[output:02e8ff5f] %[output:45c20a08] %[output:8de8017e] %[output:7c1ca537] %[output:8f55b56a] %[output:802bcbc7] %[output:6325fbd8] %[output:7656ee01] %[output:9d257861] %[output:6de50f24] %[output:13262997] %[output:7940e136] %[output:78e12ac8] %[output:06c3032f] %[output:505db29e] %[output:07868670] %[output:8b7637fa] %[output:2dc50865] %[output:7a202e2e] %[output:3b335258] %[output:340c105f] %[output:45bd952c] %[output:6d3a350b] %[output:947c2699] %[output:3378c2de] %[output:2ed18173] %[output:0a104c19] %[output:0f39da05] %[output:6ec9f0b4] %[output:93e21ff1] %[output:371ac3d9] %[output:54fbfde4] %[output:89024e34] %[output:8d9a759d]
cl = NG_FFCutsFits.(selectCuts);
NG_FFCutsFits.(selectCuts) = [cl{:}];

beep
beep
beep
%%

all_fit_par = NG_FFCutsFits.([selectCuts,'_all_fit_par']);
bg_data = extract_bg_par(all_fit_par,[1,2]);
acolor b
% original slope parameters
pd(bg_data(1));lx(all_fit_par(1).en,all_fit_par(end).en); keep_figure; %[output:445a8e9e]
pd(bg_data(2));lx(all_fit_par(1).en,all_fit_par(end).en);keep_figure %[output:0ef0ca80]
%pd(bg_data(3));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure;
%pd(bg_data(4));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure
[S_eff,J0_eff,G_eff] = extract_fit_par(all_fit_par );
pd(S_eff); keep_figure; %[output:31043882]
pd(J0_eff);keep_figure %[output:492d2640]
pd(G_eff); keep_figure; %[output:4b72a26c]
%%

doc = matlab.desktop.editor.getActive;
doc.save;
thisFile = 'e:\SHARE\Fe\Data\analysis\06_fit_with_AQ0\fit_cutFe_NG.mlx';
targ_file = fullfile(fileparts(thisFile),['fit_cutFe_NG_',selectCuts,'.pdf']);
export(thisFile,targ_file);
%close all;
%end
%%
fit_src_struc = NG_FFCutsFits;
save(CutFitFileNG,"fit_src_struc",'-v7.3')

